int PartitionMarked(SqList &L, int s, int t, bool &ci, bool &cj) {
    int i = s, j = t, m = (s + t) / 2;
    KeyType x = MidKey(L.r[s].key, L.r[m].key, L.r[t].key);
    ci = cj = false;
    while (i < j) {
        while (i < j && L.r[i].key <= x) {
            ++i;
            if (L.r[i].key < L.r[i - 1].key) {
                RedType z = L.r[i]; L.r[i] = L.r[i - 1]; L.r[i - 1] = z; ci = true;
            }
        }
        while (j > i && L.r[j].key > x) {
            --j;
            if (L.r[j].key > L.r[j + 1].key) {
                RedType z = L.r[j]; L.r[j] = L.r[j + 1]; L.r[j + 1] = z; cj = true;
            }
        }
        if (i < j) {
            RedType z = L.r[i]; L.r[i] = L.r[j]; L.r[j] = z;
            if (i > s && L.r[i].key < L.r[i - 1].key) ci = true;
            if (j < t && L.r[j].key > L.r[j + 1].key) cj = true;
        }
    }
    return i;
}
void MarkedQuickSort(SqList &L, int s, int t) {
    if (s >= t) return;
    bool ci, cj; int i = PartitionMarked(L, s, t, ci, cj);
    if (ci) MarkedQuickSort(L, s, i - 1);
    if (cj) MarkedQuickSort(L, i, t);
}
~~~~

ci 或 cj 为假表示题给划分已认证相应侧有序，故可剪枝；有标记的一侧继续处理。划分保持左侧关键字不大于 x、右侧大于 x，按区间长度归纳可得整体有序。

严格递增的最佳输入且 $N\ge4$ 时，只作一次划分，两个标记均假。题给扫描与相邻检测作 $2N-1$ 次关键字比较；上面的三者取中在递增分支作 2 次，故总数为

$$\boxed{2N+1}\quad(N\ge4),$$

最佳时间为 $\Theta(N)$。一般情况下，划分仍可能极不均衡，最坏时间为 $O(N^2)$、递归栈为 $O(N)$；划分较均衡时为 $O(N\log N)$ 时间、$O(\log N)$ 栈。小规模直接处理：$N=1$ 为 0、$N=2$ 为 1；按题给循环，$N=3$ 的递增输入为 4 次扫描比较加 2 次取中，即 6 次。若 MidKey 固定使用 3 次比较，上式相应加 1。

